17- Quelle valeur sera-t-elle retournée par l'appel F(7) de la fonction F suivante?
int F(int n) {
    int F0 = 0, F1 = 1, F, i;
    if (n == 0) return F0;
    else if (n == 1) return F1;
    else {
        for (i = 2; i < n; ++i) {
            F = F0 + F1;
            F0 = F1;
            F1 = F;
        }
